-- Initial schema. See docs/dev/database.md.
--
-- Written once for SQLite and PostgreSQL. Two tokens are replaced per dialect
-- before goose runs this file (internal/store/migrate.go):
--   {{pk}}  INTEGER PRIMARY KEY (SQLite) / BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY (PostgreSQL)
--   {{ts}}  TIMESTAMP (SQLite) / TIMESTAMPTZ (PostgreSQL)

-- +goose Up
CREATE TABLE event (
  id                 INTEGER PRIMARY KEY CHECK (id = 1),
  name               TEXT NOT NULL,
  starts_at          {{ts}},
  ends_at            {{ts}},
  freeze_at          {{ts}},
  time_zone          TEXT NOT NULL DEFAULT 'UTC',
  max_team_size      INTEGER NOT NULL DEFAULT 4 CHECK (max_team_size >= 1),
  scoring_mode       TEXT NOT NULL DEFAULT 'static' CHECK (scoring_mode IN ('static','dynamic')),
  registration_open  BOOLEAN NOT NULL DEFAULT TRUE,
  teams_locked       BOOLEAN NOT NULL DEFAULT FALSE,
  public_challenges  BOOLEAN NOT NULL DEFAULT FALSE,
  flag_rate_limit    INTEGER NOT NULL DEFAULT 10,
  settings           TEXT NOT NULL DEFAULT '{}',
  updated_at         {{ts}} NOT NULL
);

CREATE TABLE brackets (
  id                     {{pk}},
  name                   TEXT NOT NULL UNIQUE,
  description            TEXT NOT NULL DEFAULT '',
  requires_verification  BOOLEAN NOT NULL DEFAULT FALSE,
  position               INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE teams (
  id              {{pk}},
  name            TEXT NOT NULL,
  name_key        TEXT NOT NULL UNIQUE,
  country         TEXT,
  bracket_id      BIGINT NOT NULL REFERENCES brackets(id),
  invite_code     TEXT NOT NULL UNIQUE,
  recruiting      BOOLEAN NOT NULL DEFAULT FALSE,
  captain_id      BIGINT,
  hidden          BOOLEAN NOT NULL DEFAULT FALSE,
  prize_eligible  BOOLEAN NOT NULL DEFAULT TRUE,
  banned_at       {{ts}},
  created_at      {{ts}} NOT NULL
);

CREATE TABLE users (
  id             {{pk}},
  name           TEXT NOT NULL,
  name_key       TEXT NOT NULL UNIQUE,
  email          TEXT NOT NULL,
  email_key      TEXT NOT NULL UNIQUE,
  password_hash  TEXT NOT NULL,
  role           TEXT NOT NULL DEFAULT 'player' CHECK (role IN ('player','support','author','admin','owner')),
  team_id        BIGINT REFERENCES teams(id),
  country        TEXT,
  totp_secret    TEXT,
  verified_at    {{ts}},
  banned_at      {{ts}},
  created_at     {{ts}} NOT NULL
);
CREATE INDEX users_team ON users(team_id);

CREATE TABLE sessions (
  id_hash       TEXT PRIMARY KEY,
  user_id       BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at    {{ts}} NOT NULL,
  last_seen_at  {{ts}} NOT NULL,
  expires_at    {{ts}} NOT NULL,
  ip            TEXT,
  user_agent    TEXT
);
CREATE INDEX sessions_user ON sessions(user_id);

CREATE TABLE password_resets (
  token_hash  TEXT PRIMARY KEY,
  user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at  {{ts}} NOT NULL,
  used_at     {{ts}}
);

CREATE TABLE challenges (
  id              {{pk}},
  slug            TEXT NOT NULL UNIQUE,
  name            TEXT NOT NULL,
  category        TEXT NOT NULL,
  difficulty      TEXT,
  author          TEXT NOT NULL DEFAULT '',
  description_md  TEXT NOT NULL,
  connection      TEXT,
  value           INTEGER NOT NULL,
  min_value       INTEGER,
  decay           INTEGER,
  state           TEXT NOT NULL DEFAULT 'visible' CHECK (state IN ('visible','hidden','retired')),
  visible_from    {{ts}},
  requires        TEXT NOT NULL DEFAULT '[]',
  theme_fields    TEXT NOT NULL DEFAULT '{}',
  tags            TEXT NOT NULL DEFAULT '[]',
  position        INTEGER NOT NULL DEFAULT 0,
  created_at      {{ts}} NOT NULL,
  updated_at      {{ts}} NOT NULL
);

CREATE TABLE flags (
  id            {{pk}},
  challenge_id  BIGINT NOT NULL REFERENCES challenges(id) ON DELETE CASCADE,
  kind          TEXT NOT NULL CHECK (kind IN ('exact','case-insensitive','pattern','per-team')),
  value_hash    TEXT,
  pattern       TEXT,
  team_id       BIGINT REFERENCES teams(id) ON DELETE CASCADE,
  CHECK ((kind = 'pattern') = (pattern IS NOT NULL))
);
CREATE INDEX flags_challenge ON flags(challenge_id);

CREATE TABLE files (
  id            {{pk}},
  challenge_id  BIGINT NOT NULL REFERENCES challenges(id) ON DELETE CASCADE,
  name          TEXT NOT NULL,
  storage_key   TEXT NOT NULL,
  size          BIGINT NOT NULL,
  sha256        TEXT NOT NULL,
  UNIQUE (challenge_id, name)
);

CREATE TABLE hints (
  id            {{pk}},
  challenge_id  BIGINT NOT NULL REFERENCES challenges(id) ON DELETE CASCADE,
  cost          INTEGER NOT NULL DEFAULT 0 CHECK (cost >= 0),
  content_md    TEXT NOT NULL,
  position      INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE hint_unlocks (
  team_id      BIGINT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  hint_id      BIGINT NOT NULL REFERENCES hints(id) ON DELETE CASCADE,
  user_id      BIGINT REFERENCES users(id) ON DELETE SET NULL,
  cost         INTEGER NOT NULL,
  unlocked_at  {{ts}} NOT NULL,
  PRIMARY KEY (team_id, hint_id)
);

CREATE TABLE submissions (
  id            {{pk}},
  team_id       BIGINT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id       BIGINT REFERENCES users(id) ON DELETE SET NULL,
  challenge_id  BIGINT NOT NULL REFERENCES challenges(id) ON DELETE CASCADE,
  correct       BOOLEAN NOT NULL,
  submitted     TEXT NOT NULL,
  ip            TEXT,
  submitted_at  {{ts}} NOT NULL
);
CREATE INDEX submissions_team_time ON submissions(team_id, submitted_at);
CREATE INDEX submissions_challenge_time ON submissions(challenge_id, submitted_at);

CREATE TABLE solves (
  team_id        BIGINT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  challenge_id   BIGINT NOT NULL REFERENCES challenges(id) ON DELETE CASCADE,
  user_id        BIGINT REFERENCES users(id) ON DELETE SET NULL,
  submission_id  BIGINT NOT NULL REFERENCES submissions(id),
  solved_at      {{ts}} NOT NULL,
  PRIMARY KEY (team_id, challenge_id)
);
CREATE INDEX solves_challenge_time ON solves(challenge_id, solved_at);

CREATE TABLE score_adjustments (
  id          {{pk}},
  team_id     BIGINT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  points      INTEGER NOT NULL,
  reason      TEXT NOT NULL CHECK (length(reason) >= 5),
  actor_id    BIGINT NOT NULL REFERENCES users(id),
  created_at  {{ts}} NOT NULL
);

CREATE TABLE announcements (
  id         {{pk}},
  title      TEXT NOT NULL,
  body_md    TEXT NOT NULL,
  pinned     BOOLEAN NOT NULL DEFAULT FALSE,
  posted_at  {{ts}} NOT NULL,
  author_id  BIGINT REFERENCES users(id) ON DELETE SET NULL
);

CREATE TABLE pages (
  slug        TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  body_md     TEXT NOT NULL,
  visible     BOOLEAN NOT NULL DEFAULT TRUE,
  position    INTEGER NOT NULL DEFAULT 0,
  updated_at  {{ts}} NOT NULL
);

CREATE TABLE themes (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  version       TEXT NOT NULL,
  source        TEXT NOT NULL CHECK (source IN ('bundled','uploaded')),
  manifest      TEXT NOT NULL,
  installed_at  {{ts}} NOT NULL
);

CREATE TABLE theme_settings (
  id            {{pk}},
  theme_id      TEXT NOT NULL REFERENCES themes(id),
  version       INTEGER NOT NULL,
  status        TEXT NOT NULL CHECK (status IN ('draft','live','archived','scheduled')),
  data          TEXT NOT NULL DEFAULT '{}',
  custom_css    TEXT NOT NULL DEFAULT '',
  publish_at    {{ts}},
  published_by  BIGINT REFERENCES users(id),
  published_at  {{ts}},
  UNIQUE (theme_id, version)
);

CREATE TABLE challenge_services (
  challenge_id  BIGINT PRIMARY KEY REFERENCES challenges(id) ON DELETE CASCADE,
  runtime       TEXT NOT NULL CHECK (runtime IN ('docker','kubernetes')),
  ref           TEXT NOT NULL,
  status        TEXT NOT NULL,
  checked_at    {{ts}}
);

CREATE TABLE audit_log (
  id        {{pk}},
  actor_id  BIGINT REFERENCES users(id) ON DELETE SET NULL,
  action    TEXT NOT NULL,
  target    TEXT,
  before    TEXT,
  after     TEXT,
  ip        TEXT,
  at        {{ts}} NOT NULL
);
CREATE INDEX audit_log_at ON audit_log(at);

-- +goose Down
DROP TABLE audit_log;
DROP TABLE challenge_services;
DROP TABLE theme_settings;
DROP TABLE themes;
DROP TABLE pages;
DROP TABLE announcements;
DROP TABLE score_adjustments;
DROP TABLE solves;
DROP TABLE submissions;
DROP TABLE hint_unlocks;
DROP TABLE hints;
DROP TABLE files;
DROP TABLE flags;
DROP TABLE challenges;
DROP TABLE password_resets;
DROP TABLE sessions;
DROP TABLE users;
DROP TABLE teams;
DROP TABLE brackets;
DROP TABLE event;
